  endif
-%}
<!-- ============================================
     NUR PROTOCOL — SECTION 1: HERO (cover image, uncropped)
     Uses the shop file NURP.Cover.png directly — the campaign
     graphic already carries its own logo, headline and Skincoach
     panel, so no text is overlaid on top of it and nothing is
     cropped (natural aspect ratio, no forced 100vh + object-fit).
     ============================================ -->

<style>
  .nur-hero-cover {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background-color: #0A0A0A;
  }

  .nur-hero-cover__img {
    display: block;
    width: 100%;
    height: auto;
  }
</style>

<section class="nur-hero-cover">
  <img
    class="nur-hero-cover__img"
    src="{{ 'nur-protocol-hero-cover-v3.webp' | asset_url }}"
    {% if nur_fr %}alt="Masque LED IA visage et cou Nur Protocol avec l’application Nur Skincoach"{% else %}alt="Nur Protocol AI LED Face and Neck Mask with Nur Skincoach app"{% endif %}
    loading="eager">
</section>

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
    assign nur_root = ''
  endif
-%}
<!-- ============================================
     NUR PROTOCOL — SECTION 2: SOCIAL PROOF BAR (Marquee)
     Paste into a "Custom Liquid" block in Shopify Dawn
     ============================================ -->

<style>
  .nur-proof {
    width: 100%;
    overflow: hidden;
    background-color: #FFFFFF;
    border-top: 1px solid #F0EDE8;
    border-bottom: 1px solid #F0EDE8;
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    padding: 20px 0;
    position: relative;
  }

  /* Soft fade edges */
  .nur-proof::before,
  .nur-proof::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 80px;
    z-index: 2;
    pointer-events: none;
  }
  .nur-proof::before {
    left: 0;
    background: linear-gradient(to right, #FFFFFF, transparent);
  }
  .nur-proof::after {
    right: 0;
    background: linear-gradient(to left, #FFFFFF, transparent);
  }

  .nur-proof__track {
    display: flex;
    width: max-content;
    animation: nur-scroll 28s linear infinite;
  }

  .nur-proof__track:hover {
    animation-play-state: paused;
  }

  @keyframes nur-scroll {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
  }

  .nur-proof__set {
    display: flex;
    align-items: center;
    gap: 0;
    flex-shrink: 0;
  }

  .nur-proof__item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 40px;
    white-space: nowrap;
  }

  .nur-proof__icon {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
  }

  .nur-proof__icon svg {
    width: 20px;
    height: 20px;
    stroke: #C8A96E;
    fill: none;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .nur-proof__stars {
    display: flex;
    gap: 3px;
  }

  .nur-proof__star {
    width: 13px;
    height: 13px;
    fill: #C8A96E;
    stroke: none;
  }

  .nur-proof__label {
    font-size: 12px;
    font-weight: 500;
    color: #4A4A4A;
    letter-spacing: 0.8px;
    text-transform: uppercase;
  }

  .nur-proof__highlight {
    color: #C8A96E;
    font-weight: 600;
  }
</style>

<section class="nur-proof">
  <div class="nur-proof__track">
    <!-- Set 1 -->
    <div class="nur-proof__set">
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Technologie beauté avancée<{% else %}>Advanced Beauty Tech<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M9 12l2 2 4-4"/><path d="M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20z"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Soin visage + cou<{% else %}>Face + Neck Coverage<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Technologie 7 longueurs d’onde<{% else %}>Seven-Wavelength Technology<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M21 11.5a8.38 8.38 0 0 1-4.7 7.6 8.5 8.5 0 0 1-3.8.9 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>
        </div>
        <span class="nur-proof__label">{% if nur_fr %}Le <span class="nur-proof__highlight">premier</span> masque LED avec un Skincoach IA{% else %}<span class="nur-proof__highlight">First</span> LED Mask With an AI Skincoach{% endif %}</span>
      </div>

    </div>
    <!-- Set 2 (duplicate for seamless loop) -->
    <div class="nur-proof__set">
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Technologie beauté avancée<{% else %}>Advanced Beauty Tech<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M9 12l2 2 4-4"/><path d="M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20z"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Soin visage + cou<{% else %}>Face + Neck Coverage<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
        </div>
        <span class="nur-proof__label"{% if nur_fr %}>Technologie 7 longueurs d’onde<{% else %}>Seven-Wavelength Technology<{% endif %}/span>
      </div>
      <div class="nur-proof__item">
        <div class="nur-proof__icon">
          <svg viewBox="0 0 24 24"><path d="M21 11.5a8.38 8.38 0 0 1-4.7 7.6 8.5 8.5 0 0 1-3.8.9 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>
        </div>
        <span class="nur-proof__label">{% if nur_fr %}Le <span class="nur-proof__highlight">premier</span> masque LED avec un Skincoach IA{% else %}<span class="nur-proof__highlight">First</span> LED Mask With an AI Skincoach{% endif %}</span>
      </div>

    </div>
  </div>
</section>

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
