<!-- ============================================
     NUR PROTOCOL — SECTION 3: THREE DIFFERENTIATORS (v3)
     Rebuilt for editorial restraint after the CurrentBody reference:
     big uncropped imagery, one-line captions, a single understated
     underlined link per card instead of paragraphs + bordered
     detail rows.
     ============================================ -->

<style>
  .nur-diff3-wrap {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background-color: #FAFAF8;
    padding: 96px 40px 100px;
  }

  .nur-diff3__inner {
    max-width: 1320px;
    margin: 0 auto;
  }

  .nur-diff3__header {
    text-align: center;
    max-width: 560px;
    margin: 0 auto 56px;
  }

  .nur-diff3__eyebrow {
    display: inline-block;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #C8A96E;
    margin-bottom: 18px;
  }

  .nur-diff3__title {
    font-size: clamp(26px, 3.5vw, 40px);
    font-weight: 300;
    line-height: 1.15;
    color: #1A1A1A;
    margin: 0;
    letter-spacing: -0.5px;
  }

  .nur-diff3__title em { font-style: italic; color: #C8A96E; }

  .nur-diff3__rating {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-top: 18px;
  }

  .nur-diff3__rating-stars {
    display: flex;
    gap: 2px;
  }

  .nur-diff3__rating-star {
    width: 14px;
    height: 14px;
    fill: #C8A96E;
    stroke: none;
  }

  .nur-diff3__rating-text {
    font-size: 12.5px;
    font-weight: 500;
    color: #5A5A5A;
    letter-spacing: 0.2px;
  }

  .nur-diff3__rating-text strong {
    color: #1A1A1A;
    font-weight: 700;
  }

  .nur-diff3__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
  }

  .nur-diff3__card {
    display: flex;
    flex-direction: column;
  }

  .nur-diff3__media {
    aspect-ratio: 1 / 1;
    overflow: hidden;
    background-color: #F0EDE8;
    margin-bottom: 22px;
  }

  .nur-diff3__media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.6s ease;
  }

  .nur-diff3__media img.nur-diff3__media-img--top {
    object-position: center top;
  }

  .nur-diff3__card:hover .nur-diff3__media img {
    transform: scale(1.03);
  }

  .nur-diff3__heading {
    font-size: 18px;
    font-weight: 500;
    color: #1A1A1A;
    margin: 0 0 8px;
    letter-spacing: -0.1px;
  }

  .nur-diff3__text {
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.6;
    color: #7A7A7A;
    margin: 0 0 14px;
  }

  .nur-diff3__link {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    font-weight: 600;
    color: #FFFFFF;
    background: #1A1A1A;
    text-decoration: none;
    border: 1.5px solid #1A1A1A;
    border-radius: 0;
    padding: 11px 22px;
    width: fit-content;
    cursor: pointer;
    transition: background 0.3s ease, color 0.3s ease, border-color 0.3s ease, gap 0.3s ease;
  }

  .nur-diff3__link-arrow {
    transition: transform 0.3s ease;
  }

  .nur-diff3__link:hover {
    background: transparent;
    color: #1A1A1A;
    border-color: #1A1A1A;
    gap: 11px;
  }

  .nur-diff3__link:hover .nur-diff3__link-arrow {
    transform: translateX(2px);
  }

  @media (max-width: 1024px) {
    .nur-diff3__grid {
      grid-template-columns: 1fr;
      max-width: 460px;
      margin: 0 auto;
      gap: 48px;
    }
  }

  @media (max-width: 640px) {
    .nur-diff3-wrap { padding: 64px 20px 64px; }
    .nur-diff3__header { margin-bottom: 40px; }
  }
</style>

<div class="nur-diff3-wrap">
  <div class="nur-diff3__inner">

    <div class="nur-diff3__header">
      <span class="nur-diff3__eyebrow"{% if nur_fr %}>Pourquoi NŪR Protocol<{% else %}>Why NŪR Protocol<{% endif %}/span>
      <h2 class="nur-diff3__title">{% if nur_fr %}Votre peau n’est pas standard<br><em>Pourquoi votre masque le serait-il</em>{% else %}Your skin isn't generic<br><em>Why would your mask be</em>{% endif %}</h2>
      <div class="nur-diff3__rating">
        <span class="nur-diff3__rating-text"{% if nur_fr %}>Technologie beauté avancée<{% else %}>Advanced Beauty Tech<{% endif %}/span>
      </div>
    </div>

    <div class="nur-diff3__grid">

      <div class="nur-diff3__card">
        <div class="nur-diff3__media">
          <img src="{{ 'nur-protocol-worn-front-face-neck.webp' | asset_url }}" {% if nur_fr %}alt="Masque visage et dispositif cou Nur Protocol portés ensemble"{% else %}alt="Nur Protocol face mask and neck device worn together"{% endif %} loading="lazy">
        </div>
        <h3 class="nur-diff3__heading">{% if nur_fr %}Visage et cou<br>Tous deux inclus{% else %}Face and neck<br>Both included{% endif %}</h3>
        <p class="nur-diff3__text">{% if nur_fr %}Votre cou n’est pas un détail. Il mérite le même soin que votre visage : nous les avons donc conçus pour fonctionner ensemble, jamais vendus séparément, jamais en option payante.{% else %}Your neck is not an afterthought. It deserves the same care as your face, so we built them to work as one: never sold apart, never an upsell.{% endif %}</p>
        <a href="{{ nur_root }}/products/nur-protocol" class="nur-diff3__link">{% if nur_fr %}Découvrir le coffret <{% else %}Shop the set <{% endif %}span class="nur-diff3__link-arrow">&rarr;</span></a>
      </div>

      <div class="nur-diff3__card">
        <div class="nur-diff3__media">
          <img class="nur-diff3__media-img--top" src="{{ 'nur-skincoach-app-guide-v2.webp' | asset_url }}" {% if nur_fr %}alt="Carte d’accès IA Nur Skincoach et protocole LED personnalisé"{% else %}alt="Nur Skincoach AI access card and personalised LED protocol"{% endif %} loading="lazy">
        </div>
        <h3 class="nur-diff3__heading">{% if nur_fr %}Votre protocole<br>Personnalisé{% else %}Your protocol<br>Personalised{% endif %}</h3>
        <p class="nur-diff3__text">{% if nur_fr %}Une carte QR dans le coffret débloque l’application NŪR Skincoach complète et votre plan de séances.{% else %}A QR card in the box unlocks the full NŪR Skincoach app and your session plan.{% endif %}</p>
        <a href="#" class="nur-diff3__link" onclick="nurOpenChat(); return false;">{% if nur_fr %}Essayer l’aperçu <{% else %}Try the preview <{% endif %}span class="nur-diff3__link-arrow">&rarr;</span></a>
      </div>

      <div class="nur-diff3__card">
        <div class="nur-diff3__media">
          <img src="{{ 'nur-protocol-worn-led-glow-v2.webp' | asset_url }}" {% if nur_fr %}alt="Femme tenant le masque Nur Protocol contre son visage, LED allumées"{% else %}alt="Woman holding the Nur Protocol mask to her face, LEDs lit"{% endif %} loading="lazy">
        </div>
        <h3 class="nur-diff3__heading">{% if nur_fr %}Pas un réglage standard<br>Le vôtre{% else %}Not one setting<br>Yours{% endif %}</h3>
        <p class="nur-diff3__text">{% if nur_fr %}NŪR Skincoach adapte chaque séance à votre peau, pas à un préréglage d’usine identique pour tout le monde.{% else %}NŪR Skincoach matches the session to your skin, not a factory preset everyone gets.{% endif %}</p>
        <a href="#" class="nur-diff3__link" onclick="nurOpenChat(); return false;">{% if nur_fr %}Essayer l’aperçu <{% else %}Try the preview <{% endif %}span class="nur-diff3__link-arrow">&rarr;</span></a>
      </div>

    </div>

  </div>
</div>

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
    assign nur_root = ''
  endif
-%}
<!-- ============================================
     NUR PROTOCOL — SECTION 4: GUARANTEES BAR (Marquee) + FINAL CTA
     Paste into a "Custom Liquid" block in Shopify Dawn
     ============================================ -->

<style>
  .nur-guarantees {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background-color: #FFFFFF;
    border-top: 1px solid #F0EDE8;
  }

  /* --- Marquee bar --- */
  .nur-guarantees__marquee {
    width: 100%;
    overflow: hidden;
    padding: 18px 0;
    position: relative;
    border-bottom: 1px solid #F0EDE8;
  }

  .nur-guarantees__marquee::before,
  .nur-guarantees__marquee::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 60px;
    z-index: 2;
    pointer-events: none;
  }
  .nur-guarantees__marquee::before {
    left: 0;
    background: linear-gradient(to right, #FFFFFF, transparent);
  }
  .nur-guarantees__marquee::after {
    right: 0;
    background: linear-gradient(to left, #FFFFFF, transparent);
  }

  .nur-guarantees__track {
    display: flex;
    width: max-content;
    animation: nur-guar-scroll 22s linear infinite;
  }

  .nur-guarantees__track:hover {
    animation-play-state: paused;
  }

  @keyframes nur-guar-scroll {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
  }

  .nur-guarantees__set {
    display: flex;
    align-items: center;
    gap: 0;
    flex-shrink: 0;
  }

  .nur-guarantees__item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 44px;
    white-space: nowrap;
  }

  .nur-guarantees__icon {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
  }

  .nur-guarantees__icon svg {
    width: 18px;
    height: 18px;
    stroke: #C8A96E;
    fill: none;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .nur-guarantees__label {
    font-size: 11px;
    font-weight: 500;
    color: #5A5A5A;
    letter-spacing: 1px;
    text-transform: uppercase;
  }

  /* --- CTA block --- */
  .nur-guarantees__cta-wrapper {
    text-align: center;
    padding: 56px 40px 64px;
    max-width: 1320px;
    margin: 0 auto;
  }

  .nur-guarantees__cta-text {
    font-size: 16px;
    font-weight: 300;
    color: #8A8A8A;
    margin: 0 0 28px;
    font-style: italic;
    letter-spacing: 0.3px;
  }

  .nur-guarantees__cta {
    display: inline-block;
    padding: 18px 52px;
    background-color: #1A1A1A;
    color: #FFFFFF;
    text-decoration: none;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    border: 2px solid #1A1A1A;
    border-radius: 3px;
    transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  .nur-guarantees__cta:hover {
    background-color: #C8A96E;
    border-color: #C8A96E;
    color: #FFFFFF;
  }

  @media (max-width: 768px) {
    .nur-guarantees__cta-wrapper {
      padding: 40px 24px 50px;
    }
    .nur-guarantees__cta {
      padding: 16px 36px;
    }
  }
</style>

<section class="nur-guarantees">
