  <div class="nur-guarantees__marquee">
    <div class="nur-guarantees__track">
      <!-- Set 1 -->
      <div class="nur-guarantees__set">
        <div class="nur-guarantees__item">
          <div class="nur-guarantees__icon">
            <svg viewBox="0 0 24 24"><rect x="1" y="3" width="15" height="13" rx="2"/><path d="M16 8h4l3 3v5a1 1 0 0 1-1 1h-2"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
