        </div>
        <div class="nur-guarantees__item">
          <div class="nur-guarantees__icon">
            <svg viewBox="0 0 24 24"><rect x="1" y="3" width="15" height="13" rx="2"/><path d="M16 8h4l3 3v5a1 1 0 0 1-1 1h-2"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
          </div>
          <span class="nur-guarantees__label"{% if nur_fr %}>Livré en 15 jours<{% else %}>Delivered in 15 Days<{% endif %}/span>
        </div>
      </div>
      <!-- Set 2 (duplicate for seamless loop) -->
      <div class="nur-guarantees__set">
        <div class="nur-guarantees__item">
          <div class="nur-guarantees__icon">
            <svg viewBox="0 0 24 24"><rect x="1" y="3" width="15" height="13" rx="2"/><path d="M16 8h4l3 3v5a1 1 0 0 1-1 1h-2"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
          </div>
          <span class="nur-guarantees__label"{% if nur_fr %}>Livraison dans le monde entier<{% else %}>Worldwide Shipping<{% endif %}/span>
