<script>
  (function () {
    var row = document.getElementById('nurBaRow');
    var prevBtn = document.getElementById('nurBaPrev');
    var nextBtn = document.getElementById('nurBaNext');
    if (!row) return;

    function cardStep() {
      var card = row.querySelector('.nur-ba__card');
      if (!card) return 320;
      var gap = parseFloat(getComputedStyle(row).gap) || 20;
      return card.getBoundingClientRect().width + gap;
    }

    window.nurBaScroll = function (direction) {
      row.scrollBy({ left: direction * cardStep(), behavior: 'smooth' });
    };

    function updateNav() {
      var max = row.scrollWidth - row.clientWidth - 2;
      prevBtn.disabled = row.scrollLeft <= 2;
      nextBtn.disabled = row.scrollLeft >= max;
    }

    row.addEventListener('scroll', updateNav, { passive: true });
    window.addEventListener('resize', updateNav);
    updateNav();
  })();
</script>

